 9 | contract ReferralFeePoolV0 is IReferralFeePool {
10 |     IMochiEngine public immutable engine;
11 |     IUniswapV2Router02 public immutable uniswapRouter;
12 | 
13 |     uint256 public rewards;
14 | 
15 |     mapping(address => uint256) public reward;
16 | 
17 |     constructor(address _engine, address _uniswap) {
18 |         engine = IMochiEngine(_engine);
19 |         uniswapRouter = IUniswapV2Router02(_uniswap);
20 |     }
21 | 
22 |     function addReward(address _recipient) external override {
23 |         uint256 newReward = engine.usdm().balanceOf(address(this)) - rewards;
24 |         reward[_recipient] += newReward;
25 |         rewards += newReward;
26 |     }
27 | 
28 |     function claimRewardAsMochi() external {
29 |         IUSDM usdm = engine.usdm();
30 |         address[] memory path = new address[](2);
31 |         path[0] = address(usdm);
32 |         path[1] = uniswapRouter.WETH();
33 |         path[2] = address(engine.mochi());
34 |         usdm.approve(address(uniswapRouter), reward[msg.sender]);
35 |         // we are going to ingore the slippages here
36 |         uniswapRouter.swapExactTokensForTokens(
37 |             reward[msg.sender],
38 |             1,
39 |             path,
40 |             address(this),
41 |             type(uint256).max
42 |         );
43 |         engine.mochi().transfer(
44 |             msg.sender,
45 |             engine.mochi().balanceOf(address(this))
46 |         );
47 |     }
48 | }
